const assetImageData = [];
const libraryIcons = ['assets/library-icon.png', 'assets/media-cover.png'];
const offlineBytes = new Map();
const offlineLoads = new Map();
function loadOfflineAsset(path) {
 if (offlineLoads.has(path)) return offlineLoads.get(path);
 const load = new Promise((resolve, reject) => {
  const script = document.createElement('script');
  script.src = new URL(path + '.js', document.baseURI).href;
  script.onload = () => {
   script.remove();
   const data = offlineBytes.get(path);
   if (!data) { reject(new Error('Aset lokal tidak lengkap: ' + path)); return; }
   offlineBytes.delete(path);
   resolve(Uint8Array.from(atob(data), c => c.charCodeAt(0)).buffer);
  };
  script.onerror = () => {
   script.remove();
   reject(new Error('Aset tidak ditemukan. Ekstrak seluruh isi ZIP, termasuk folder assets, lalu buka kembali index.html.'));
  };
  document.head.appendChild(script);
 }).catch(error => { offlineLoads.delete(path); throw error; });
 offlineLoads.set(path, load);
 return load;
}
async function assetBytes(url) {
 if (new URL(document.baseURI).protocol === 'file:') return loadOfflineAsset(url);
 const response = await fetch(new URL(url, document.baseURI));
 if (!response.ok) throw new Error('Gagal memuat ' + url + ' (HTTP ' + response.status + ')');
 return response.arrayBuffer();
}
async function imageData(url) {
 const blob = new Blob([await assetBytes(url)], {type: 'image/png'});
 return new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = () => resolve(reader.result);
  reader.onerror = () => reject(reader.error);
  reader.readAsDataURL(blob);
 });
}
