async function exportSugar(m,period,cutoff){
 const pictureEntries = await Promise.all(Object.entries(sugarImages).map(async ([key, url]) => [key, await imageData(url)]));
 const pictures = Object.fromEntries(pictureEntries);
 await Promise.all(libraryIcons.map(async (url, i) => { assetImageData[i] = await imageData(url); }));

 const base=await sugarDeck(m,period,cutoff,pictures).write({outputType:'arraybuffer'});
 const deck=await JSZip.loadAsync(base),design=await JSZip.loadAsync(await assetBytes('assets/sugar-design.zip'));
 const slidePath='ppt/slides/slide1.xml';
 const fresh=xml(await deck.file(slidePath).async('string')),fields={};
 function capture(k,element){
  fields[k]=nodes(element,'t').map(t=>t.textContent).join('');
  const run=first(element,'rPr');
  if(run)fields[k+'color']=first(run,'srgbClr')?.getAttribute('val')||'121C2C';
 }
 for(const shape of nodes(fresh,'sp')){
  const name=first(shape,'cNvPr').getAttribute('name');
  if(name.startsWith('Text '))capture('s'+name.slice(5),shape);
 }
 nodes(fresh,'tbl').forEach((table,i)=>nodes(table,'tr').forEach((row,r)=>nodes(row,'tc').forEach((cell,c)=>capture('t'+i+'_'+r+'_'+c,cell))));
 const relPath='ppt/slides/_rels/slide1.xml.rels';
 const slideRels=xml(await deck.file(relPath).async('string'));
 const chartPaths=nodes(slideRels,'Relationship').filter(r=>r.getAttribute('Type').endsWith('/chart')).map(r=>new URL(r.getAttribute('Target'),'https://local/ppt/slides/slide1.xml').pathname.slice(1));
 const layout=await design.file(slidePath).async('string');
 deck.file(slidePath,layout.replace(/\{\{(\w+)\}\}/g,(_,k)=>{if(!(k in fields))throw Error('Data slide belum lengkap: '+k);return esc(fields[k])}));
 for(const file of Object.keys(design.files)){
  if(file.startsWith('ppt/media/'))deck.file(file,await design.file(file).async('uint8array'));
 }
 const branchSlide='ppt/slides/slide2.xml',branchRels='ppt/slides/_rels/slide2.xml.rels';
 const branch=await deck.file(branchSlide).async('string');
 const header=await design.file('header.xml').async('string');
 deck.file(branchSlide,branch.replace(/<p:pic>[\s\S]*?<\/p:pic>/g,pic=>pic.includes('name="Image 0"')?header:pic));
 const links=await design.file('header.rels').async('string');
 deck.file(branchRels,(await deck.file(branchRels).async('string')).replace('</Relationships>',links+'</Relationships>'));
 const relStyle=await design.file(relPath).async('string');
 deck.file(relPath,relStyle.replace(/\.\.\/charts\/chart([12])\.xml/g,(_,i)=>'/'+chartPaths[i-1]));
 for(let i=1;i<=2;i++){
  const path=chartPaths[i-1];
  const data=await deck.file(path).async('string'),parts=data.match(/<c:ser>[\s\S]*?<\/c:ser>/g);
  let j=0,style=await design.file('ppt/charts/chart'+i+'.xml').async('string');
  style=style.replace(/<c:ser>[\s\S]*?<\/c:ser>/g,series=>{
   const source=parts[j++];for(const name of ['tx','cat','val']){
    const matcher=new RegExp('<c:'+name+'>[\\s\\S]*?</c:'+name+'>');
    series=series.replace(matcher,()=>source.match(matcher)[0]);
   }return series;
  });
  if(i===1)style=style.replace(/<c:max val="[^"]+"\s*\/>/,()=>data.match(/<c:max val="[^"]+"\s*\/>/)[0]);
  deck.file(path,style);
 }
 const types='[Content_Types].xml';let content=await deck.file(types).async('string');
 for(const [ext,type] of [['wdp','image/vnd.ms-photo'],['jpeg','image/jpeg']])if(!content.includes('Extension="'+ext+'"'))content=content.replace('</Types>','<Default Extension="'+ext+'" ContentType="'+type+'"/></Types>');
 deck.file(types,content);return deck.generateAsync({type:'blob',compression:'DEFLATE',mimeType:'application/vnd.openxmlformats-officedocument.presentationml.presentation'});
}
let sugarData=sugarModel(sugarExample),sugarBusy=false,sugarSerial=0;
const su=id=>document.getElementById('sugar'+id);
function sugarCutoff(){
 const v=su('Date').value;if(!v)return '';
 const date=new Date(v+'T00:00:00Z');date.setUTCDate(date.getUTCDate()-1);
 return date.toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
}
function sugarRender(){
 const target=su('Preview');target.replaceChildren();
 su('Export').disabled=!sugarData||sugarBusy||!su('Period').value.trim()||!sugarCutoff();
 if(!sugarData)return;
 const m=sugarData,r=m.real.at(-1),t=m.tickets.at(-1);
 el('h2',target,(su('Page').value==='2'?'Profile Assurance Guarantee · Branch':'Evaluasi Assurance Guarantee')+' · '+su('Period').value);
 if(su('Page').value==='2'){
  for(let i=1;i<=4;i++){el('h3',target,'Area '+i);const area=m.areas[i];
   const tbl=grid(target,['Branch','Real','ACH','Tiket GAUL','F-F','F-L','L-F','L-L'],[...area.rows,area.total].map(a=>a.map((v,j)=>j===0?v:j===1?sf(v,2):j===2?sp(v):sf(v))));
   [...area.rows,area.total].forEach((row,i)=>{if(row[2]<1){const c=tbl.rows[i+1].cells[2];c.style.background='#c00000';c.style.color='white'}})}
 }else{
  grid(target,['Periode','Realisasi','vs Target','ACH','Growth'],[[r.label,sf(r.v[1],2)+'%',sf(r.v[1]-r.v[0],2)+' p.p.',sp(m.summary.at(-1)[3]),sp(m.summary.at(-1)[4])]]);
  el('h3',target,'Tren Tiket GAUL dan Non GAUL');grid(target,['Periode','Line Gaul','Line Gangguan','Tiket Gangguan'],m.tickets.map(v=>[v.label,...v.v.map(n=>sf(n))]));
  el('p',target,'Perubahan total tiket '+t.label+' terhadap '+(m.tickets.at(-2)?.label||'—')+' • '+(m.growth===null?'—':sp(m.growth)));
 }
}
