su('File').onchange=async()=>{
 const seq=++sugarSerial,f=su('File').files[0];sugarData=null;sugarRender();if(!f)return;
 su('Msg').textContent='Memuat Excel…';
 try{const m=sugarModel(await ttrWorkbook(f,sugarSheets));if(seq!==sugarSerial)return;
 const label=m.real.at(-1).label,year=f.name.match(/\b20\d{2}\b/)?.[0]||'';
 su('Period').value=periodFromName(label+' '+year)||[label,year].filter(Boolean).join(' ');
 su('Date').value='';sugarData=m;su('Msg').textContent='Excel termuat. Isi tanggal data untuk menghitung cut off H−1.'}
 catch(e){if(seq===sugarSerial)su('Msg').textContent='Gagal memuat Excel. '+e.message}finally{if(seq===sugarSerial)sugarRender()}
};
for(const id of ['Date','Period','Page'])su(id).oninput=sugarRender;
su('Export').onclick=async()=>{if(su('Export').disabled)return;sugarBusy=true;sugarRender();try{const period=su('Period').value.trim();const blob=await exportSugar(sugarData,period,sugarCutoff());const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Evaluasi_SUGAR_'+period.replace(/[^\w-]+/g,'_')+'.pptx';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),10000)}catch(e){su('Msg').textContent='Ekspor gagal. '+e.message}finally{sugarBusy=false;sugarRender()}};

