 for(let c=2;c<d[2].length;c++)if(clean(d[2][c])==='AUTO ONLINE'&&clean(d[2][c+1])==='ASSIGN'&&d[1]?.[c]!=null&&d[7]?.[c]!=null)months.push({name:String(d[1][c]),rows:Array.from({length:5},(_,i)=>[0,1,2].map(k=>num(d,i+3,c+k)))});
