  let rows=[];for(let r=1;r<b.length;r++){
   const label=String(b[r]?.[start]??'').trim();if(label==='BRANCH'){rows=[];continue}
   if(!label||typeof b[r]?.[start+1]!=='number')continue;
   const val=[label,...Array.from({length:8},(_,j)=>num(b,r,start+j+1)),b[r][start+9]??'–'];
   const row={val,colors:val.map((v,j)=>colors(v,r,start+j))};const m=label.match(/^AREA\s*([1-4])$/i);
   if(m){areas[m[1]]={rows,total:row};rows=[]}else rows.push(row);
  }
